-- ===== CONVERSATION THREADING SİSTEMİ =====
-- 1. Conversations tablosuna thread yapısı ekle ALTER TABLE conversations ADD COLUMN IF NOT EXISTS thread_id UUID DEFAULT NULL, ADD COLUMN IF NOT EXISTS parent_message_id INTEGER DEFAULT NULL, ADD COLUMN IF NOT EXISTS message_order INTEGER DEFAULT 1;
-- 2. Thread ID için index ekle CREATE INDEX IF NOT EXISTS idx_conversations_thread_id ON conversations(thread_id); CREATE INDEX IF NOT EXISTS idx_conversations_parent_message ON conversations(parent_message_id); CREATE INDEX IF NOT EXISTS idx_conversations_thread_order ON conversations(thread_id, message_order);
-- 3. Mevcut conversations'ları thread'lere organize et -- Her conversation kendi thread'inin ilk mesajı olarak ayarla UPDATE conversations SET thread_id = gen_random_uuid(), message_order = 1 WHERE thread_id IS NULL;
-- 4. Thread başlıkları için view oluştur CREATE OR REPLACE VIEW conversation_threads AS SELECT c.thread_id, c.user_id, first_msg.question as thread_title, first_msg.created_at as thread_created_at, last_msg.created_at as last_updated_at, COUNT(c.id) as message_count, first_msg.id as first_message_id, last_msg.id as last_message_id FROM conversations c LEFT JOIN conversations first_msg ON ( first_msg.thread_id = c.thread_id AND first_msg.message_order = 1 ) LEFT JOIN conversations last_msg ON ( last_msg.thread_id = c.thread_id AND last_msg.message_order = ( SELECT MAX(message_order) FROM conversations WHERE thread_id = c.thread_id ) ) WHERE c.thread_id IS NOT NULL GROUP BY c.thread_id, c.user_id, first_msg.question, first_msg.created_at, last_msg.created_at, first_msg.id, last_msg.id;
-- 5. Thread mesajları için function oluştur CREATE OR REPLACE FUNCTION get_thread_messages(target_thread_id UUID) RETURNS TABLE ( id INTEGER, thread_id UUID, parent_message_id INTEGER, message_order INTEGER, question TEXT, answer TEXT, model_name TEXT, confidence FLOAT, sources JSONB, response_time FLOAT, user_id UUID, created_at TIMESTAMP WITH TIME ZONE ) LANGUAGE SQL STABLE AS $$ SELECT c.id, c.thread_id, c.parent_message_id, c.message_order, c.question, c.answer, c.model_name, c.confidence, c.sources, c.response_time, c.user_id, c.created_at FROM conversations c WHERE c.thread_id = target_thread_id ORDER BY c.message_order ASC; $$;
-- 6. Yeni thread oluşturma function'ı CREATE OR REPLACE FUNCTION create_new_thread() RETURNS UUID LANGUAGE SQL AS $$ SELECT gen_random_uuid(); $$;
-- 7. Thread'e mesaj ekleme function'ı CREATE OR REPLACE FUNCTION get_next_message_order(target_thread_id UUID) RETURNS INTEGER LANGUAGE SQL STABLE AS $$ SELECT COALESCE(MAX(message_order), 0) + 1 FROM conversations WHERE thread_id = target_thread_id; $$;
-- 8. RLS policy'lerini thread yapısına uygun güncelle DROP POLICY IF EXISTS "Users can view own conversations" ON conversations; DROP POLICY IF EXISTS "Users can insert own conversations" ON conversations; DROP POLICY IF EXISTS "Users can update own conversations" ON conversations; DROP POLICY IF EXISTS "Users can delete own conversations" ON conversations;
-- Thread-aware policy'ler CREATE POLICY "Users can view own conversation threads" ON conversations FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can insert into own conversation threads" ON conversations FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can update own conversation threads" ON conversations FOR UPDATE USING (auth.uid() = user_id);
CREATE POLICY "Users can delete own conversation threads" ON conversations FOR DELETE USING (auth.uid() = user_id);
-- 9. Thread istatistikleri için view CREATE OR REPLACE VIEW user_thread_stats AS SELECT user_id, COUNT(DISTINCT thread_id) as total_threads, SUM(message_count) as total_messages, AVG(message_count) as avg_messages_per_thread, MAX(last_updated_at) as last_activity_at FROM conversation_threads GROUP BY user_id;

import time
from datetime import datetime

from fastapi import FastAPI, HTTPException, Query, Depends, Header
from fastapi.responses import StreamingResponse
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel
from typing import Optional, Dict, List, Any
import uvicorn
import json
from fastapi.middleware.cors import CORSMiddleware

from rag_system import RAGRetriever
from ollama_rag import OllamaRAGQA
from supabase_client import SupabaseLogger


# ====== REQUEST/RESPONSE MODELS ======

class GenerateRequest(BaseModel):
    question: str
    top_k: Optional[int] = 3
    user_id: Optional[str] = None
    thread_id: Optional[str] = None  # Thread ID olarak değiştir (UUID string)


class GenerateResponse(BaseModel):
    answer: str
    confidence: float
    method: str
    sources: List[Dict[str, Any]]


class AuthRequest(BaseModel):
    email: str
    password: str


class SignUpRequest(BaseModel):
    email: str
    password: str
    full_name: Optional[str] = None


app = FastAPI(
    title="RAG API",
    description="Ollama RAG A",
    version="1.0.0"
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

retriever = None
qa_system = None
supabase_logger = None
security = HTTPBearer(auto_error=False)


# ====== AUTH DEPENDENCY ======

async def get_current_user(credentials: Optional[HTTPAuthorizationCredentials] = Depends(security)):
    """JWT token'dan kullanıcı bilgilerini çıkar (opsiyonel)"""
    if not credentials:
        print(" get_current_user: Token bulunamadı")
        return None

    if not supabase_logger:
        print(" get_current_user: Supabase logger yok")
        return None

    try:
        print(f" get_current_user: Token alındı - {credentials.credentials[:20]}...")
        user_info = supabase_logger.get_user(credentials.credentials)
        if user_info["success"]:
            print(f"✅ get_current_user: Kullanıcı doğrulandı - {user_info['user'].email}")
            return user_info["user"]
        else:
            print(f"❌ get_current_user: Token geçersiz - {user_info.get('message', 'Bilinmeyen hata')}")
        return None
    except Exception as e:
        print(f"❌ get_current_user exception: {e}")
        return None


async def require_auth(user = Depends(get_current_user)):
    """Auth zorunlu endpoint'ler için"""
    if not user:
        raise HTTPException(
            status_code=401, 
            detail="Authentication required",
            headers={"WWW-Authenticate": "Bearer"}
        )
    return user


@app.on_event("startup")
async def startup_event():
    global retriever, qa_system, supabase_logger

    print(" RAG API başlatılıyor...")

    try:
        retriever = RAGRetriever()
        retriever.load_from_files("faiss_index.bin", "documents.pkl")
        qa_system = OllamaRAGQA(retriever, model_name="gemma3")
        supabase_logger = SupabaseLogger()

        print("RAG sistemi başarıyla yüklendi.")
        print("Supabase başarıyla bağlandı ve çalışıyor!")
    except Exception as e:
        print(f"RAG sistemi yüklenirken hata oluştu: {e}")
        supabase_logger = None


@app.get("/")
async def root():
    return {
        "status": "active",
        "message": "RAG API çalışıyor! POST /generate endpoint'ini kullanın."
    }


@app.get("/status")
async def check_status():
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    ollama_status = qa_system.check_ollama_status()

    return {
        "rag_system": "ready" if retriever else "not_loaded",
        "ollama_status": "online" if ollama_status else "offline",
        "model": qa_system.model_name,
        "index_status": "loaded" if retriever.index is not None else "not_loaded",
        "document_count": len(retriever.documents) if retriever.documents else 0,
        "supabase_auth": "available" if supabase_logger else "unavailable"
    }


# ====== AUTHENTICATION ENDPOINTS ======

@app.post("/auth/signup")
async def signup(request: SignUpRequest):
    """Yeni kullanıcı kaydı"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    metadata = {"full_name": request.full_name} if request.full_name else None
    result = supabase_logger.sign_up(request.email, request.password, metadata)

    if result["success"]:
        return {
            "message": result["message"],
            "user_id": result["user"].id if result["user"] else None
        }
    else:
        raise HTTPException(status_code=400, detail=result["message"])


@app.post("/auth/signin")
async def signin(request: AuthRequest):
    """Kullanıcı girişi"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    result = supabase_logger.sign_in(request.email, request.password)

    if result["success"]:
        return {
            "message": result["message"],
            "access_token": result["access_token"],
            "clear_chat": True,
            "user": {
                "id": result["user"].id,
                "email": result["user"].email,
                "created_at": result["user"].created_at
            }
        }
    else:
        raise HTTPException(status_code=401, detail=result["message"])


@app.post("/auth/signout")
async def signout():
    """Kullanıcı çıkışı"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    result = supabase_logger.sign_out()
    return {"message": result["message"]}


@app.get("/auth/me")
async def get_me(user = Depends(require_auth)):
    """Mevcut kullanıcı bilgilerini getir"""
    return {
        "user": {
            "id": user.id,
            "email": user.email,
            "created_at": user.created_at,
            "user_metadata": user.user_metadata
        }
    }


@app.get("/auth/stats")
async def get_user_stats(user = Depends(require_auth)):
    """Kullanıcının conversation istatistiklerini getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    stats = supabase_logger.get_user_stats(user.id)
    if stats["success"]:
        return stats["stats"]
    else:
        raise HTTPException(status_code=500, detail=stats["message"])


@app.get("/auth/models")
async def get_user_models(user = Depends(require_auth)):
    """Kullanıcının kullandığı modelleri getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    models = supabase_logger.get_user_models(user.id)
    return {"models": models}


# ====== RAG ENDPOINTS ======


@app.post("/generate", response_model=GenerateResponse)
async def generate(request: GenerateRequest, current_user = Depends(get_current_user)):
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    # Authenticated user'ın ID'sini kullan, yoksa request'teki user_id'yi kullan
    user_id = current_user.id if current_user else request.user_id

    start_time = time.time()
    conversation_saved = False
    conversation_id = None
    thread_id = None

    try:
        result = qa_system.answer_question(
            question=request.question,
            top_k=request.top_k
        )

        response_time = time.time() - start_time

        # Chat kaydetme işlemini güçlendir ve SENKRON yap
        if supabase_logger and result.get("answer"):
            try:
                conversation_result = supabase_logger.log_conversation_with_id(
                    question=request.question,
                    answer=result["answer"],
                    model_name=qa_system.model_name,
                    confidence=result.get("confidence", 0),
                    sources=result.get("sources", []),
                    response_time=response_time,
                    user_id=user_id,
                    thread_id=request.thread_id  # thread_id olarak düzelt
                )
                if conversation_result["success"]:
                    conversation_saved = True
                    conversation_id = conversation_result["conversation_id"]
                    thread_id = conversation_result["thread_id"]
                    print(f"✓ Conversation kaydedildi (ID: {conversation_id}, Thread: {thread_id}, User: {user_id or 'Anonymous'})")
                else:
                    print(f"✗ Conversation kaydetme başarısız (User: {user_id or 'Anonymous'})")
            except Exception as save_error:
                print(f"❌ Conversation kaydetme hatası: {save_error}")
        else:
            if not supabase_logger:
                print("⚠️ Supabase logger mevcut değil - conversation kaydedilmedi!")
            elif not result.get("answer"):
                print("⚠️ Boş answer - conversation kaydedilmedi!")

        return {
            "answer": result["answer"],
            "confidence": result.get("confidence", 0),
            "method": result.get("method", "unknown"),
            "sources": result.get("sources", []),
            "conversation_saved": conversation_saved,
            "conversation_id": conversation_id,
            "thread_id": thread_id if conversation_saved else None,
            "user_authenticated": current_user is not None
        }

    except Exception as e:
        print(f"❌ Generate endpoint hatası: {str(e)}")
        raise HTTPException(status_code=500, detail=f"İşlem sırasında hata oluştu: {str(e)}")


@app.post("/generate-stream")
async def generate_stream(request: GenerateRequest, current_user = Depends(get_current_user)):
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    # Authenticated user'ın ID'sini kullan, yoksa request'teki user_id'yi kullan
    user_id = current_user.id if current_user else request.user_id

    start_time = time.time()
    full_answer = ""

    try:
        search_results = retriever.search(request.question, request.top_k)
        context = retriever.get_context_for_query(request.question, request.top_k)

        async def event_generator():
            nonlocal full_answer
            try:
                yield "data: " + json.dumps({
                    "type": "start",
                    "message": "Yanıt oluşturuluyor...",
                    "sources_count": len(search_results),
                    "authenticated": current_user is not None
                }) + "\n\n"

                for chunk in qa_system.generate_answer_stream(request.question, context):
                    if chunk:
                        full_answer += chunk  # Chunk'ları biriktir
                        yield "data: " + json.dumps({
                            "type": "chunk",
                            "text": chunk
                        }) + "\n\n"

                response_time = time.time() - start_time
                top_confidence = search_results[0]['score'] if search_results else 0
                conversation_saved = False
                conversation_id = None
                thread_id = None

                # Chat kaydetme işlemini güçlendir ve senkron yap
                if supabase_logger and full_answer.strip():
                    try:
                        conversation_result = supabase_logger.log_conversation_with_id(
                            question=request.question,
                            answer=full_answer,
                            model_name=qa_system.model_name,
                            confidence=top_confidence,
                            sources=search_results[:4],
                            response_time=response_time,
                            user_id=user_id,
                            thread_id=request.thread_id  # thread_id parametresini ekle
                        )
                        if conversation_result["success"]:
                            conversation_saved = True
                            conversation_id = conversation_result["conversation_id"]
                            thread_id = conversation_result["thread_id"]
                            print(f"✓ Streaming conversation kaydedildi (ID: {conversation_id}, Thread: {thread_id}, User: {user_id or 'Anonymous'})")
                        else:
                            print(f"✗ Streaming conversation kaydetme başarısız (User: {user_id or 'Anonymous'})")
                    except Exception as save_error:
                        print(f"❌ Streaming conversation kaydetme hatası: {save_error}")
                else:
                    if not supabase_logger:
                        print("⚠️ Supabase logger mevcut değil - streaming conversation kaydedilmedi!")
                    elif not full_answer.strip():
                        print("⚠️ Boş answer - streaming conversation kaydedilmedi!")

                yield "data: " + json.dumps({
                    "type": "end",
                    "sources": search_results[:4],
                    "confidence": top_confidence,
                    "method": "ollama_with_rag" if context else "ollama_general",
                    "conversation_saved": conversation_saved,
                    "conversation_id": conversation_id,
                    "thread_id": thread_id if conversation_saved else None,
                    "user_authenticated": current_user is not None
                }) + "\n\n"

            except Exception as e:
                print(f"❌ Streaming generator hatası: {str(e)}")
                yield "data: " + json.dumps({
                    "type": "error",
                    "message": f"Hata oluştu: {str(e)}"
                }) + "\n\n"

        return StreamingResponse(
            event_generator(),
            media_type="text/event-stream",
            headers={
                'Cache-Control': 'no-cache',
                'Connection': 'keep-alive',
                'X-Accel-Buffering': 'no',
            }
        )

    except Exception as e:
        print(f"❌ Streaming endpoint hatası: {str(e)}")
        raise HTTPException(status_code=500, detail=f"İşlem sırasında hata oluştu: {str(e)}")

@app.get("/history")
async def get_history(
    current_user = Depends(require_auth),  # Auth zorunlu yap
    limit: int = Query(50)
):
    """Konuşma geçmişini getir - Thread sistemi ile uyumlu (backward compatibility için)"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Thread sistemi kullan - eski conversation history yerine
    threads = supabase_logger.get_conversation_threads(current_user.id, limit)

    # Eski format için dönüştür (backward compatibility)
    conversations = []
    for thread in threads:
        conversations.append({
            "id": thread.get("first_message_id"),
            "thread_id": thread.get("thread_id"),
            "question": thread.get("thread_title"),
            "created_at": thread.get("thread_created_at"),
            "last_updated_at": thread.get("last_updated_at"),
            "message_count": thread.get("message_count", 1)
        })

    return {
        "conversations": conversations,
        "user_authenticated": True,
        "user_id": current_user.id,
        "total_conversations": len(conversations),
        "showing": len(conversations),
        "limit": limit,
        "note": "Bu endpoint thread sistemi kullanıyor. /threads endpoint'ini kullanmanız önerilir."
    }


@app.get("/history/search")
async def search_history(
    search: str = Query(..., min_length=1),
    current_user = Depends(require_auth),
    limit: int = Query(20)
):
    """Authenticated user'ın conversation'larında arama yap"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    results = supabase_logger.search_conversations(current_user.id, search, limit)

    return {
        "conversations": results,
        "search_term": search,
        "found": len(results),
        "user_id": current_user.id
    }


@app.get("/history/{conversation_id}")
async def get_conversation_by_id(
    conversation_id: int,
    current_user = Depends(get_current_user)
):
    """Belirli bir conversation'ın detaylarını getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Conversation'ı getir
    conversation = supabase_logger.get_conversation_by_id(conversation_id, current_user.id if current_user else None)

    if not conversation:
        raise HTTPException(status_code=404, detail="Conversation bulunamadı")

    return {
        "conversation": conversation,
        "user_authenticated": current_user is not None
    }

@app.delete("/history/{conversation_id}")
async def delete_conversation(
    conversation_id: int,
    current_user = Depends(require_auth)
):
    """Belirli bir conversation'ı sil"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    success = supabase_logger.delete_conversation(conversation_id, current_user.id)

    if success:
        return {"message": "Conversation başarıyla silindi", "conversation_id": conversation_id}
    else:
        raise HTTPException(status_code=404, detail="Conversation bulunamadı veya silinirken hata oluştu")


@app.get("/history/count")
async def get_conversation_count(current_user = Depends(require_auth)):
    """Kullanıcının toplam conversation sayısını getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    count = supabase_logger.get_conversation_count(current_user.id)

    return {
        "user_id": current_user.id,
        "total_conversations": count
    }

@app.get("/history/latest")
async def get_latest_conversations(
    current_user = Depends(require_auth),
    limit: int = Query(5, description="Son kaç conversation getirileceği")
):
    """En son conversation'ları getir - real-time güncellemeler için"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Thread sistemi kullan
    threads = supabase_logger.get_conversation_threads(current_user.id, limit)

    # Eski format için dönüştür
    conversations = []
    for thread in threads:
        conversations.append({
            "id": thread.get("first_message_id"),
            "thread_id": thread.get("thread_id"),
            "question": thread.get("thread_title"),
            "created_at": thread.get("thread_created_at"),
            "last_updated_at": thread.get("last_updated_at"),
            "message_count": thread.get("message_count", 1)
        })

    return {
        "conversations": conversations,
        "user_id": current_user.id,
        "count": len(conversations),
        "timestamp": datetime.utcnow().isoformat()
    }

@app.get("/threads")
async def get_conversation_threads(
    current_user = Depends(require_auth),
    limit: int = Query(50)
):
    """Kullanıcının conversation thread'lerini getir (yeni thread sistemi)"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Thread'leri getir
    threads = supabase_logger.get_conversation_threads(current_user.id, limit)

    return {
        "threads": threads,
        "user_authenticated": True,
        "user_id": current_user.id,
        "showing": len(threads),
        "limit": limit
    }

@app.get("/threads/{thread_id}/messages")
async def get_thread_messages(
    thread_id: str,
    current_user = Depends(require_auth)
):
    """Belirli bir thread'in tüm mesajlarını getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Thread'in mesajlarını getir
    messages = supabase_logger.get_thread_messages(thread_id, current_user.id)

    if not messages:
        raise HTTPException(status_code=404, detail="Thread bulunamadı veya erişim izni yok")

    return {
        "thread_id": thread_id,
        "messages": messages,
        "message_count": len(messages),
        "user_authenticated": True
    }

@app.delete("/threads/{thread_id}")
async def delete_thread(
    thread_id: str,
    current_user = Depends(require_auth)
):
    """Belirli bir thread'i ve tüm mesajlarını sil"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    try:
        # Thread'e ait tüm mesajları sil
        result = supabase_logger.supabase.table("conversations").delete().eq("thread_id", thread_id).eq("user_id", current_user.id).execute()

        if result.data:
            print(f"✅ Thread silindi - ID: {thread_id}, Silinen mesaj sayısı: {len(result.data)}")
            return {
                "message": "Thread ve tüm mesajları başarıyla silindi",
                "thread_id": thread_id,
                "deleted_messages": len(result.data)
            }
        else:
            print(f"❌ Thread bulunamadı - ID: {thread_id}")
            raise HTTPException(status_code=404, detail="Thread bulunamadı veya erişim izni yok")

    except Exception as e:
        print(f"❌ Thread silme hatası: {e}")
        raise HTTPException(status_code=500, detail="Thread silinirken hata oluştu")

if __name__ == "__main__":
    uvicorn.run("rag_api:app", host="0.0.0.0", port=8000, reload=True)

import time
from datetime import datetime

from fastapi import FastAPI, HTTPException, Query, Depends, Header
from fastapi.responses import StreamingResponse
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel
from typing import Optional, Dict, List, Any
import uvicorn
import json
from fastapi.middleware.cors import CORSMiddleware

from rag_system import RAGRetriever
from ollama_rag import OllamaRAGQA
from supabase_client import SupabaseLogger


# ====== REQUEST/RESPONSE MODELS ======

class GenerateRequest(BaseModel):
    question: str
    top_k: Optional[int] = 3
    user_id: Optional[str] = None
    thread_id: Optional[str] = None  # Thread ID olarak değiştir (UUID string)


class GenerateResponse(BaseModel):
    answer: str
    confidence: float
    method: str
    sources: List[Dict[str, Any]]


class AuthRequest(BaseModel):
    email: str
    password: str


class SignUpRequest(BaseModel):
    email: str
    password: str
    full_name: Optional[str] = None


app = FastAPI(
    title="RAG API",
    description="Ollama RAG A",
    version="1.0.0"
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

retriever = None
qa_system = None
supabase_logger = None
security = HTTPBearer(auto_error=False)


# ====== AUTH DEPENDENCY ======

async def get_current_user(credentials: Optional[HTTPAuthorizationCredentials] = Depends(security)):
    """JWT token'dan kullanıcı bilgilerini çıkar (opsiyonel)"""
    if not credentials:
        print(" get_current_user: Token bulunamadı")
        return None

    if not supabase_logger:
        print(" get_current_user: Supabase logger yok")
        return None

    try:
        print(f" get_current_user: Token alındı - {credentials.credentials[:20]}...")
        user_info = supabase_logger.get_user(credentials.credentials)
        if user_info["success"]:
            print(f"✅ get_current_user: Kullanıcı doğrulandı - {user_info['user'].email}")
            return user_info["user"]
        else:
            print(f"❌ get_current_user: Token geçersiz - {user_info.get('message', 'Bilinmeyen hata')}")
        return None
    except Exception as e:
        print(f"❌ get_current_user exception: {e}")
        return None


async def require_auth(user = Depends(get_current_user)):
    """Auth zorunlu endpoint'ler için"""
    if not user:
        raise HTTPException(
            status_code=401, 
            detail="Authentication required",
            headers={"WWW-Authenticate": "Bearer"}
        )
    return user


@app.on_event("startup")
async def startup_event():
    global retriever, qa_system, supabase_logger

    print(" RAG API başlatılıyor...")

    try:
        retriever = RAGRetriever()
        retriever.load_from_files("faiss_index.bin", "documents.pkl")
        qa_system = OllamaRAGQA(retriever, model_name="gemma3")
        supabase_logger = SupabaseLogger()

        print("RAG sistemi başarıyla yüklendi.")
        print("Supabase başarıyla bağlandı ve çalışıyor!")
    except Exception as e:
        print(f"RAG sistemi yüklenirken hata oluştu: {e}")
        supabase_logger = None


@app.get("/")
async def root():
    return {
        "status": "active",
        "message": "RAG API çalışıyor! POST /generate endpoint'ini kullanın."
    }


@app.get("/status")
async def check_status():
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    ollama_status = qa_system.check_ollama_status()

    return {
        "rag_system": "ready" if retriever else "not_loaded",
        "ollama_status": "online" if ollama_status else "offline",
        "model": qa_system.model_name,
        "index_status": "loaded" if retriever.index is not None else "not_loaded",
        "document_count": len(retriever.documents) if retriever.documents else 0,
        "supabase_auth": "available" if supabase_logger else "unavailable"
    }


# ====== AUTHENTICATION ENDPOINTS ======

@app.post("/auth/signup")
async def signup(request: SignUpRequest):
    """Yeni kullanıcı kaydı"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    metadata = {"full_name": request.full_name} if request.full_name else None
    result = supabase_logger.sign_up(request.email, request.password, metadata)

    if result["success"]:
        return {
            "message": result["message"],
            "user_id": result["user"].id if result["user"] else None
        }
    else:
        raise HTTPException(status_code=400, detail=result["message"])


@app.post("/auth/signin")
async def signin(request: AuthRequest):
    """Kullanıcı girişi"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    result = supabase_logger.sign_in(request.email, request.password)

    if result["success"]:
        return {
            "message": result["message"],
            "access_token": result["access_token"],
            "clear_chat": True,
            "user": {
                "id": result["user"].id,
                "email": result["user"].email,
                "created_at": result["user"].created_at
            }
        }
    else:
        raise HTTPException(status_code=401, detail=result["message"])


@app.post("/auth/signout")
async def signout():
    """Kullanıcı çıkışı"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Auth servisi mevcut değil")

    result = supabase_logger.sign_out()
    return {"message": result["message"]}


@app.get("/auth/me")
async def get_me(user = Depends(require_auth)):
    """Mevcut kullanıcı bilgilerini getir"""
    return {
        "user": {
            "id": user.id,
            "email": user.email,
            "created_at": user.created_at,
            "user_metadata": user.user_metadata
        }
    }


@app.get("/auth/stats")
async def get_user_stats(user = Depends(require_auth)):
    """Kullanıcının conversation istatistiklerini getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    stats = supabase_logger.get_user_stats(user.id)
    if stats["success"]:
        return stats["stats"]
    else:
        raise HTTPException(status_code=500, detail=stats["message"])


@app.get("/auth/models")
async def get_user_models(user = Depends(require_auth)):
    """Kullanıcının kullandığı modelleri getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    models = supabase_logger.get_user_models(user.id)
    return {"models": models}


# ====== RAG ENDPOINTS ======


@app.post("/generate", response_model=GenerateResponse)
async def generate(request: GenerateRequest, current_user = Depends(get_current_user)):
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    # Authenticated user'ın ID'sini kullan, yoksa request'teki user_id'yi kullan
    user_id = current_user.id if current_user else request.user_id

    start_time = time.time()
    conversation_saved = False
    conversation_id = None
    thread_id = None

    try:
        result = qa_system.answer_question(
            question=request.question,
            top_k=request.top_k
        )

        response_time = time.time() - start_time

        # Chat kaydetme işlemini güçlendir ve SENKRON yap
        if supabase_logger and result.get("answer"):
            try:
                conversation_result = supabase_logger.log_conversation_with_id(
                    question=request.question,
                    answer=result["answer"],
                    model_name=qa_system.model_name,
                    confidence=result.get("confidence", 0),
                    sources=result.get("sources", []),
                    response_time=response_time,
                    user_id=user_id,
                    thread_id=request.thread_id  # thread_id olarak düzelt
                )
                if conversation_result["success"]:
                    conversation_saved = True
                    conversation_id = conversation_result["conversation_id"]
                    thread_id = conversation_result["thread_id"]
                    print(f"✓ Conversation kaydedildi (ID: {conversation_id}, Thread: {thread_id}, User: {user_id or 'Anonymous'})")
                else:
                    print(f"✗ Conversation kaydetme başarısız (User: {user_id or 'Anonymous'})")
            except Exception as save_error:
                print(f"❌ Conversation kaydetme hatası: {save_error}")
        else:
            if not supabase_logger:
                print("⚠️ Supabase logger mevcut değil - conversation kaydedilmedi!")
            elif not result.get("answer"):
                print("⚠️ Boş answer - conversation kaydedilmedi!")

        return {
            "answer": result["answer"],
            "confidence": result.get("confidence", 0),
            "method": result.get("method", "unknown"),
            "sources": result.get("sources", []),
            "conversation_saved": conversation_saved,
            "conversation_id": conversation_id,
            "thread_id": thread_id if conversation_saved else None,
            "user_authenticated": current_user is not None
        }

    except Exception as e:
        print(f"❌ Generate endpoint hatası: {str(e)}")
        raise HTTPException(status_code=500, detail=f"İşlem sırasında hata oluştu: {str(e)}")


@app.post("/generate-stream")
async def generate_stream(request: GenerateRequest, current_user = Depends(get_current_user)):
    if not qa_system or not retriever:
        raise HTTPException(status_code=500, detail="RAG sistemi henüz başlatılmadı")

    # Authenticated user'ın ID'sini kullan, yoksa request'teki user_id'yi kullan
    user_id = current_user.id if current_user else request.user_id

    start_time = time.time()
    full_answer = ""

    try:
        search_results = retriever.search(request.question, request.top_k)
        context = retriever.get_context_for_query(request.question, request.top_k)

        async def event_generator():
            nonlocal full_answer
            try:
                yield "data: " + json.dumps({
                    "type": "start",
                    "message": "Yanıt oluşturuluyor...",
                    "sources_count": len(search_results),
                    "authenticated": current_user is not None
                }) + "\n\n"

                for chunk in qa_system.generate_answer_stream(request.question, context):
                    if chunk:
                        full_answer += chunk  # Chunk'ları biriktir
                        yield "data: " + json.dumps({
                            "type": "chunk",
                            "text": chunk
                        }) + "\n\n"

                response_time = time.time() - start_time
                top_confidence = search_results[0]['score'] if search_results else 0
                conversation_saved = False
                conversation_id = None
                thread_id = None

                # Chat kaydetme işlemini güçlendir ve senkron yap
                if supabase_logger and full_answer.strip():
                    try:
                        conversation_result = supabase_logger.log_conversation_with_id(
                            question=request.question,
                            answer=full_answer,
                            model_name=qa_system.model_name,
                            confidence=top_confidence,
                            sources=search_results[:4],
                            response_time=response_time,
                            user_id=user_id,
                            thread_id=request.thread_id  # thread_id parametresini ekle
                        )
                        if conversation_result["success"]:
                            conversation_saved = True
                            conversation_id = conversation_result["conversation_id"]
                            thread_id = conversation_result["thread_id"]
                            print(f"✓ Streaming conversation kaydedildi (ID: {conversation_id}, Thread: {thread_id}, User: {user_id or 'Anonymous'})")
                        else:
                            print(f"✗ Streaming conversation kaydetme başarısız (User: {user_id or 'Anonymous'})")
                    except Exception as save_error:
                        print(f"❌ Streaming conversation kaydetme hatası: {save_error}")
                else:
                    if not supabase_logger:
                        print("⚠️ Supabase logger mevcut değil - streaming conversation kaydedilmedi!")
                    elif not full_answer.strip():
                        print("⚠️ Boş answer - streaming conversation kaydedilmedi!")

                yield "data: " + json.dumps({
                    "type": "end",
                    "sources": search_results[:4],
                    "confidence": top_confidence,
                    "method": "ollama_with_rag" if context else "ollama_general",
                    "conversation_saved": conversation_saved,
                    "conversation_id": conversation_id,
                    "thread_id": thread_id if conversation_saved else None,
                    "user_authenticated": current_user is not None
                }) + "\n\n"

            except Exception as e:
                print(f"❌ Streaming generator hatası: {str(e)}")
                yield "data: " + json.dumps({
                    "type": "error",
                    "message": f"Hata oluştu: {str(e)}"
                }) + "\n\n"

        return StreamingResponse(
            event_generator(),
            media_type="text/event-stream",
            headers={
                'Cache-Control': 'no-cache',
                'Connection': 'keep-alive',
                'X-Accel-Buffering': 'no',
            }
        )

    except Exception as e:
        print(f"❌ Streaming endpoint hatası: {str(e)}")
        raise HTTPException(status_code=500, detail=f"İşlem sırasında hata oluştu: {str(e)}")

@app.get("/history")
async def get_history(
    current_user = Depends(require_auth),  # Auth zorunlu yap
    limit: int = Query(50)
):
    """Konuşma geçmişini getir - Thread sistemi ile uyumlu (backward compatibility için)"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # get_conversation_history fonksiyonunu kullan (soft delete uyumlu)
    history = supabase_logger.get_conversation_history(current_user.id, limit)

    return {
        "conversations": history,
        "user_authenticated": True,
        "user_id": current_user.id,
        "total_conversations": len(history),
        "showing": len(history),
        "limit": limit
    }


@app.get("/history/search")
async def search_history(
    search: str = Query(..., min_length=1),
    current_user = Depends(require_auth),
    limit: int = Query(20)
):
    """Authenticated user'ın conversation'larında arama yap"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    results = supabase_logger.search_conversations(current_user.id, search, limit)

    return {
        "conversations": results,
        "search_term": search,
        "found": len(results),
        "user_id": current_user.id
    }


@app.get("/history/{conversation_id}")
async def get_conversation_by_id(
    conversation_id: int,
    current_user = Depends(get_current_user)
):
    """Belirli bir conversation'ın detaylarını getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Conversation'ı getir
    conversation = supabase_logger.get_conversation_by_id(conversation_id, current_user.id if current_user else None)

    if not conversation:
        raise HTTPException(status_code=404, detail="Conversation bulunamadı")

    return {
        "conversation": conversation,
        "user_authenticated": current_user is not None
    }

@app.delete("/history/{conversation_id}")
async def delete_conversation(
    conversation_id: int,
    current_user = Depends(require_auth)
):
    """Belirli bir conversation'ı sil"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    success = supabase_logger.delete_conversation(conversation_id, current_user.id)

    if success:
        return {"message": "Conversation başarıyla silindi", "conversation_id": conversation_id}
    else:
        raise HTTPException(status_code=404, detail="Conversation bulunamadı veya silinirken hata oluştu")


@app.get("/history/count")
async def get_conversation_count(current_user = Depends(require_auth)):
    """Kullanıcının toplam conversation sayısını getir"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    count = supabase_logger.get_conversation_count(current_user.id)

    return {
        "user_id": current_user.id,
        "total_conversations": count
    }

@app.get("/history/latest")
async def get_latest_conversations(
    current_user = Depends(require_auth),
    limit: int = Query(5, description="Son kaç conversation getirileceği")
):
    """En son conversation'ları getir - real-time güncellemeler için"""
    if not supabase_logger:
        raise HTTPException(status_code=500, detail="Supabase bağlantısı yok")

    # Thread sistemi kullan
    threads = supabase_logger.get_conversation_threads(current_user.id, limit)

    # Eski format için dönüştür
    conversations = []
    for thread in threads:
        conversations.append({
            "id": thread.get("first_message_id"),
            "thread_id": thread.get("thread_id"),
            "question": thread.get("thread_title"),
            "created_at": thread.get("thread_created_at"),
            "last_updated_at": thread.get("last_updated_at"),
            "message_count": thread.get("message_count", 1)
        })

    return {
        "conversations": conversations,
        "user_id": current_user.id,
        "count": len(conversations),
        "timestamp": datetime.utcnow().isoformat()
    }

